WITH latest_rows AS (SELECT mktcode,tgtcode,bizdate,volume,turnover FROM `newzl`.`hsj_stock_hq_basic` WHERE bizdate='2026-04-14'), volume_rank AS (SELECT mktcode,tgtcode,bizdate,volume,turnover,ROW_NUMBER() OVER(ORDER BY volume DESC,mktcode,tgtcode) AS rn FROM latest_rows), candidates AS (SELECT * FROM volume_rank WHERE rn<=20 AND volume>0), turnover_rank AS (SELECT mktcode,tgtcode,bizdate,ROW_NUMBER() OVER(ORDER BY turnover DESC,mktcode,tgtcode) AS rn FROM candidates) SELECT mktcode,tgtcode,bizdate FROM turnover_rank WHERE rn<=3;
